set-variable.value:
@{
            try
            {
                var body = context.Request.Body.As<JObject>(preserveContent: true);
                return body?["model"]?.ToString() ?? "unknown";
            }
            catch { return "unknown"; }
        }

when.condition:
@{
                var requiredRole = "{{databricks-required-role}}";
                var roles = ((Jwt)context.Variables["jwt"]).Claims
                    .GetValueOrDefault("roles", "")
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                return !roles.Any(role => role.Trim().Equals(requiredRole, StringComparison.OrdinalIgnoreCase));
            }

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("message", "Access denied: required Databricks role not found in JWT"),
                                new JProperty("type", "authorization_error"),
                                new JProperty("code", "model_access_denied")
                            ))
                        ).ToString();
                    }

when.set-body:
@{
                    var body = context.Request.Body.As<JObject>(preserveContent: true);
                    if (body["stream_options"] == null)
                    {
                        body["stream_options"] = new JObject();
                    }
                    ((JObject)body["stream_options"])["include_usage"] = true;
                    return body.ToString();
                }

on-error.trace:
@{
            return string.Format("Databricks LLM request failed: {0}", context.LastError.Message);
        }
